import json
from collections import defaultdict
from datetime import timedelta

from django.core.management.base import BaseCommand, CommandParser
from django.db.models import Count, QuerySet
from django.utils import timezone

from notifications.models import OnboardingEmailQueue


class Command(BaseCommand):
    help = "Report onboarding email queue health. SENT means accepted by Django/SMTP, not Resend delivery-confirmed."

    def add_arguments(self, parser: CommandParser) -> None:
        parser.add_argument("--days", type=int, default=7)
        parser.add_argument("--stale-hours", type=int, default=24)
        parser.add_argument(
            "--status", action="append", choices=OnboardingEmailQueue.Status.values
        )
        parser.add_argument("--format", choices=("table", "json"), default="table")

    def handle(self, *args, **options) -> None:
        now = timezone.now()
        days = options["days"]
        stale_hours = options["stale_hours"]
        statuses = options.get("status") or []
        output_format = options["format"]

        since = now - timedelta(days=days)
        queryset = OnboardingEmailQueue.objects.select_related("user").filter(
            scheduled_for__gte=since
        )
        if statuses:
            queryset = queryset.filter(status__in=statuses)

        report = self._build_report(
            queryset=queryset,
            now=now,
            stale_cutoff=now - timedelta(hours=stale_hours),
        )

        if output_format == "json":
            self.stdout.write(json.dumps(report, indent=2, sort_keys=True))
            return

        self._write_table_report(report)

    def _build_report(
        self,
        *,
        queryset: QuerySet[OnboardingEmailQueue],
        now,
        stale_cutoff,
    ) -> dict:
        status_counts = {
            row["status"]: row["count"]
            for row in queryset.values("status")
            .annotate(count=Count("id"))
            .order_by("status")
        }

        track_email_counts: dict[str, dict[str, int]] = defaultdict(dict)
        for row in (
            queryset.values("onboarding_track", "email_number")
            .annotate(count=Count("id"))
            .order_by("onboarding_track", "email_number")
        ):
            track_email_counts[row["onboarding_track"]][str(row["email_number"])] = row[
                "count"
            ]

        failed_rows = [
            self._serialize_row(row)
            for row in queryset.filter(
                status=OnboardingEmailQueue.Status.FAILED
            ).order_by("-updated_at")[:25]
        ]

        stale_pending_rows = [
            self._serialize_row(row)
            for row in queryset.filter(
                status=OnboardingEmailQueue.Status.PENDING,
                scheduled_for__lte=stale_cutoff,
            ).order_by("scheduled_for")[:25]
        ]

        return {
            "generated_at": now.isoformat(),
            "sent_status_note": "SENT means accepted by Django/SMTP, not confirmed delivered by Resend.",
            "status_counts": status_counts,
            "track_email_counts": dict(track_email_counts),
            "failed_rows": failed_rows,
            "stale_pending_rows": stale_pending_rows,
        }

    def _serialize_row(self, row: OnboardingEmailQueue) -> dict:
        return {
            "id": str(row.id),
            "user_email": row.user.email,
            "username": row.user.username,
            "onboarding_track": row.onboarding_track,
            "email_number": row.email_number,
            "status": row.status,
            "scheduled_for": row.scheduled_for.isoformat(),
            "sent_at": row.sent_at.isoformat() if row.sent_at else None,
            "last_error": row.last_error,
        }

    def _write_table_report(self, report: dict) -> None:
        self.stdout.write(report["sent_status_note"])
        self.stdout.write("\nStatus counts")
        for status, count in report["status_counts"].items():
            self.stdout.write(f"  {status}: {count}")

        self.stdout.write("\nTrack/email counts")
        for track, email_counts in report["track_email_counts"].items():
            counts = ", ".join(
                f"email {email_number}: {count}"
                for email_number, count in email_counts.items()
            )
            self.stdout.write(f"  {track}: {counts}")

        self.stdout.write("\nRecent failed rows")
        if report["failed_rows"]:
            for row in report["failed_rows"]:
                self.stdout.write(
                    f"  {row['id']} {row['user_email']} email {row['email_number']}: {row['last_error']}"
                )
        else:
            self.stdout.write("  none")

        self.stdout.write("\nStale pending rows")
        if report["stale_pending_rows"]:
            for row in report["stale_pending_rows"]:
                self.stdout.write(
                    f"  {row['id']} {row['user_email']} email {row['email_number']} scheduled {row['scheduled_for']}"
                )
        else:
            self.stdout.write("  none")

