        gap: 0.5rem;
    }
    .suggestion-pill {
        padding: 0.375rem 0.75rem;
        background: #007bff;
        color: #fff;
        border: 1px solid #007bff;
        border-radius: 50rem;
        font-size: 0.875rem;
        cursor: pointer;
        transition: all 0.15s ease-in-out;
        text-decoration: none;
    }
    .suggestion-pill:hover {
        background: #0056b3;
        border-color: #0056b3;
        transform: translateY(-1px);
    }
    .suggestion-pill:active {
        transform: translateY(0);
    }
    .loading-suggestions {
        display: flex;
        align-items: center;
        gap: 0.5rem;
        font-size: 0.875rem;
        color: #6c757d;
    }
    .loading-suggestions .spinner-border {
        width: 1rem;
        height: 1rem;
        border-width: 2px;
    }
    .metadata-info {
        margin-top: 0.5rem;
        padding: 0.5rem;
        background: #f8f9fa;
        border-radius: 0.25rem;
        font-size: 0.875rem;
        color: #6c757d;
    }
</style>
{% endblock %}

