{% block extra_js %}
<script>
    document.addEventListener('DOMContentLoaded', function() {
        // File upload tab elements
        const dropArea = document.getElementById('drop-area');
        const fileInput = document.getElementById('ics_file');
        const fileSelectButton = document.getElementById('file-select-button');
        const selectedFileInfo = document.getElementById('selected-file-info');
        const fileName = document.getElementById('file-name');
        const removeFileButton = document.getElementById('remove-file');
        const importFileButton = document.getElementById('import-file-button');

        // Form elements
        const fileForm = document.getElementById('ics-file-form');
        const urlForm = document.getElementById('ics-url-form');

        // URL suggestion elements
        const icsUrlInput = document.getElementById('ics_url');
        const accountNameInput = document.getElementById('account_name_url');
        const suggestionsContainer = document.getElementById('suggestions-container');
        const suggestionPills = document.getElementById('suggestion-pills');
        const metadataInfo = document.getElementById('metadata-info');

        let fetchTimeout = null;
        let currentRequest = null;
        let lastUrl = '';

        function normalizeCalendarUrl(url) {
            const trimmedUrl = (url || '').trim();
            if (trimmedUrl.toLowerCase().startsWith('webcal://')) {
                return 'https://' + trimmedUrl.slice(9);
            }
            return trimmedUrl;
        }

        function hasSupportedCalendarUrlScheme(url) {
            const normalizedUrl = normalizeCalendarUrl(url);
            return normalizedUrl.startsWith('http://') || normalizedUrl.startsWith('https://');
        }

        // Helper to safely create a text span
        function createTextSpan(text, className) {
            const span = document.createElement('span');
            span.className = className || '';
            span.textContent = text;
            return span;
        }

        // Helper to create a suggestion pill button safely (no innerHTML)
        function createSuggestionPill(suggestion) {
            const btn = document.createElement('button');
            btn.type = 'button';
            btn.className = 'suggestion-pill';
            btn.dataset.name = suggestion;
            btn.textContent = suggestion;
            btn.addEventListener('click', function() {
                accountNameInput.value = this.dataset.name;
                accountNameInput.focus();
                // Highlight the selected pill
                suggestionPills.querySelectorAll('.suggestion-pill').forEach(p => {
                    p.style.opacity = '0.6';
                });
                this.style.opacity = '1';
            });
            return btn;
        }

        // Helper to safely render metadata info (no innerHTML)
        function renderMetadataInfo(metadata) {
            metadataInfo.textContent = '';
            const icon = document.createElement('i');
            icon.className = 'bi bi-info-circle me-1';
            metadataInfo.appendChild(icon);

            let infoText = `Found ${metadata.event_count} events`;
            if (metadata.timezone) {
                infoText += ` \u2022 Timezone: ${metadata.timezone}`;
            }
            if (metadata.description) {
                infoText += ` \u2022 ${metadata.description}`;
            }
            metadataInfo.appendChild(document.createTextNode(infoText));
            metadataInfo.style.display = 'block';
        }

        // Function to abort any pending request
        function abortPendingRequest() {
            if (currentRequest) {
                currentRequest.abort();
                currentRequest = null;
            }
            if (fetchTimeout) {
                clearTimeout(fetchTimeout);
                fetchTimeout = null;
            }
        }

        // Function to fetch calendar suggestions
        function fetchCalendarSuggestions(url) {
            // Cancel any pending request
            abortPendingRequest();

            // Normalize and validate before fetch
            const calUrl = normalizeCalendarUrl(url);
            const hasValidScheme = hasSupportedCalendarUrlScheme(calUrl);
            if (!hasValidScheme || calUrl.length < 12) {
                suggestionsContainer.style.display = 'block';
                suggestionPills.textContent = '';
                suggestionPills.appendChild(createTextSpan('Enter a valid calendar URL to see suggestions', 'text-muted'));
                metadataInfo.style.display = 'none';
                return;
            }

            // Store the URL we're fetching for to guard against stale responses
            const fetchingUrl = calUrl;

            // Show loading state
            suggestionsContainer.style.display = 'block';
            suggestionPills.textContent = '';
            const loadingDiv = document.createElement('div');
            loadingDiv.className = 'loading-suggestions';
            const spinner = document.createElement('span');
            spinner.className = 'spinner-border spinner-border-sm';
            loadingDiv.appendChild(spinner);
            loadingDiv.appendChild(document.createTextNode(' Analyzing calendar...'));
            suggestionPills.appendChild(loadingDiv);
            metadataInfo.style.display = 'none';

            // Create abort controller for cancellable requests
            const controller = new AbortController();
            currentRequest = controller;

            // Fetch suggestions from server
            fetch('{% url "calendars:get_calendar_suggestions" %}', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'X-CSRFToken': '{{ csrf_token }}'
                },
                body: JSON.stringify({ calendar_url: calUrl }),
                signal: controller.signal
            })
            .then(response => {
                if (!response.ok) {
                    throw new Error('Request failed');
                }
                return response.json();
            })
            .then(data => {
                // Guard against stale responses - check if URL still matches
                if (fetchingUrl !== lastUrl) {
                    return;
                }

                suggestionPills.textContent = '';

                if (data.suggestions && data.suggestions.length > 0) {
                    // Display suggestions as clickable pills (safe DOM creation)
                    data.suggestions.forEach(suggestion => {
                        suggestionPills.appendChild(createSuggestionPill(suggestion));
                    });

                    // Show metadata if available
                    if (data.metadata && data.metadata.event_count > 0) {
                        renderMetadataInfo(data.metadata);
                    }
                } else {
                    // No suggestions available
                    suggestionPills.appendChild(createTextSpan('Unable to fetch calendar details - you can still enter a name manually', 'text-muted'));
                }
            })
            .catch(error => {
                if (error.name !== 'AbortError') {
                    // Only show error if it wasn't an intentional abort
                    suggestionPills.textContent = '';
                    suggestionPills.appendChild(createTextSpan('Could not retrieve suggestions. Please enter a name.', 'text-muted'));
                }
            })
            .finally(() => {
                currentRequest = null;
            });
        }

        // Listen for URL input changes
        function handleUrlChange() {
            const url = normalizeCalendarUrl(icsUrlInput.value);

            if (url && url !== lastUrl) {
                lastUrl = url;

                // Clear any existing timeout
                if (fetchTimeout) {
                    clearTimeout(fetchTimeout);
                }

                // Wait a bit before fetching to avoid too many requests
                fetchTimeout = setTimeout(() => {
                    // Call fetchCalendarSuggestions for any URL with reasonable length
                    // It handles scheme validation and shows appropriate messages
                    if (url.length > 10) {
                        fetchCalendarSuggestions(url);
                    }
                }, 500); // Wait 500ms after user stops typing
            } else if (!url) {
                // Hide suggestions if URL is cleared and abort any pending request
                abortPendingRequest();
                suggestionsContainer.style.display = 'none';
                lastUrl = '';
            }
        }

        // Listen for paste, input, and change events on URL input
        icsUrlInput.addEventListener('paste', function(e) {
            setTimeout(handleUrlChange, 100);
        });
        icsUrlInput.addEventListener('input', handleUrlChange);
        icsUrlInput.addEventListener('change', handleUrlChange);

        // Reset pill opacity when name input is focused
        accountNameInput.addEventListener('focus', function() {
            if (suggestionPills.querySelector('.suggestion-pill')) {
                suggestionPills.querySelectorAll('.suggestion-pill').forEach(pill => {
                    pill.style.opacity = '1';
                });
            }
        });

        // Validation helper function
        function showFieldError(inputElement, errorMessage) {
            inputElement.classList.add('is-invalid');
            let feedback = inputElement.nextElementSibling;
            while (feedback && !feedback.classList.contains('invalid-feedback')) {
                feedback = feedback.nextElementSibling;
            }
            if (!feedback) {
                feedback = document.createElement('div');
                feedback.className = 'invalid-feedback';
                inputElement.parentNode.insertBefore(feedback, inputElement.nextSibling);
            }
            feedback.textContent = errorMessage;
            feedback.style.display = 'block';
        }

        function clearFieldError(inputElement) {
            inputElement.classList.remove('is-invalid');
            let feedback = inputElement.nextElementSibling;
            while (feedback && !feedback.classList.contains('invalid-feedback')) {
                feedback = feedback.nextElementSibling;
            }
            if (feedback && feedback.classList.contains('invalid-feedback')) {
                feedback.style.display = 'none';
            }
        }

        // Tab handling
        const tabs = document.querySelectorAll('[data-bs-toggle="tab"]');
        tabs.forEach(tab => {
            tab.addEventListener('shown.bs.tab', function(event) {
                // Reset forms when switching tabs
                if (event.target.id === 'file-tab') {
                    urlForm.reset();
                    // Reset suggestions and abort any pending request
                    abortPendingRequest();
                    suggestionsContainer.style.display = 'none';
                    lastUrl = '';
                } else if (event.target.id === 'url-tab') {
                    fileForm.reset();
                    selectedFileInfo.style.display = 'none';
                    importFileButton.disabled = true;
                }
            });
        });

        // File upload handling

        // Open file dialog when the select button is clicked
        fileSelectButton.addEventListener('click', function() {
            fileInput.click();
        });

        // Handle file selection
        fileInput.addEventListener('change', function() {
            handleFiles(this.files);
        });

        // Prevent default drag behaviors
        ['dragenter', 'dragover', 'dragleave', 'drop'].forEach(eventName => {
            dropArea.addEventListener(eventName, preventDefaults, false);
            document.body.addEventListener(eventName, preventDefaults, false);
        });

        // Highlight drop area when a file is dragged over it
        ['dragenter', 'dragover'].forEach(eventName => {
            dropArea.addEventListener(eventName, highlight, false);
        });

        ['dragleave', 'drop'].forEach(eventName => {
            dropArea.addEventListener(eventName, unhighlight, false);
        });

        // Handle dropped files
        dropArea.addEventListener('drop', handleDrop, false);

        // Remove selected file
        removeFileButton.addEventListener('click', function() {
            fileInput.value = '';
            selectedFileInfo.style.display = 'none';
            importFileButton.disabled = true;
        });

        // Form validation
        fileForm.addEventListener('submit', function(e) {
            const accountNameInput = document.getElementById('account_name_file');
            const accountName = accountNameInput.value.trim();
            let isValid = true;

            if (!accountName) {
                e.preventDefault();
                showFieldError(accountNameInput, 'Please enter a calendar name');
                isValid = false;
            } else {
                clearFieldError(accountNameInput);
            }

            if (!fileInput.files.length) {
                e.preventDefault();
                // Show error in the drop area
                dropArea.classList.add('border-danger');
                const errorDiv = document.createElement('div');
                errorDiv.className = 'text-danger mt-2';
                errorDiv.textContent = 'Please select an ICS file';
                errorDiv.id = 'file-error';
                // Remove any existing error
                const existingError = document.getElementById('file-error');
                if (existingError) {
                    existingError.remove();
                }
                dropArea.appendChild(errorDiv);
                isValid = false;
            } else {
                dropArea.classList.remove('border-danger');
                const existingError = document.getElementById('file-error');
                if (existingError) {
                    existingError.remove();
                }
            }

            return isValid;
        });

        urlForm.addEventListener('submit', function(e) {
            const accountNameInput = document.getElementById('account_name_url');
            const icsUrlInput = document.getElementById('ics_url');
            const accountName = accountNameInput.value.trim();
            const icsUrl = normalizeCalendarUrl(icsUrlInput.value);
            let isValid = true;

            if (!accountName) {
                e.preventDefault();
                showFieldError(accountNameInput, 'Please enter a calendar name');
                isValid = false;
            } else {
                clearFieldError(accountNameInput);
            }

            if (!icsUrl) {
                e.preventDefault();
                showFieldError(icsUrlInput, 'Please enter an ICS URL');
                isValid = false;
            } else if (!hasSupportedCalendarUrlScheme(icsUrl)) {
                e.preventDefault();
                showFieldError(icsUrlInput, 'Please enter a valid URL starting with http://, https://, or webcal://');
                isValid = false;
            } else {
                icsUrlInput.value = icsUrl;
                clearFieldError(icsUrlInput);
            }

            return isValid;
        });

        // Helper functions
        function preventDefaults(e) {
            e.preventDefault();
            e.stopPropagation();
        }

        function highlight() {
            dropArea.classList.add('dragover');
        }

        function unhighlight() {
            dropArea.classList.remove('dragover');
        }

        function handleDrop(e) {
            const dt = e.dataTransfer;
            const files = dt.files;
            handleFiles(files);
        }

        function handleFiles(files) {
            if (files.length) {
                const file = files[0];

                // Check if file is an ICS file
                if (file.name.toLowerCase().endsWith('.ics')) {
                    fileName.textContent = file.name;
                    selectedFileInfo.style.display = 'block';
                    importFileButton.disabled = false;
                    // Clear any error styling
                    dropArea.classList.remove('border-danger');
                    const existingError = document.getElementById('file-error');
                    if (existingError) {
                        existingError.remove();
                    }
                } else {
                    // Show error in the drop area
                    dropArea.classList.add('border-danger');
                    const errorDiv = document.createElement('div');
                    errorDiv.className = 'text-danger mt-2';
                    errorDiv.textContent = 'Please select an ICS file (.ics extension)';
                    errorDiv.id = 'file-error';
                    // Remove any existing error
                    const existingError = document.getElementById('file-error');
                    if (existingError) {
                        existingError.remove();
                    }
                    dropArea.appendChild(errorDiv);
                    fileInput.value = '';
                    selectedFileInfo.style.display = 'none';
                    importFileButton.disabled = true;
                }
            }
        }
    });
</script>
